    NEW.bus_option    := NULLIF(NEW.answers ->> 'busOption', '');
    NEW.song_request  := NULLIF(NEW.answers ->> 'songRequest', '');
    NEW.message       := NULLIF(NEW.answers ->> 'message', '');

    RETURN NEW;
END;
